CREATE OR REPLACE FUNCTION public.gestion_socios() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; RETURN jsonb_build_object('pagos',(SELECT coalesce(jsonb_agg(to_jsonb(p)),'[]'::jsonb) FROM public.pagos p),'roles',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) FROM public.usuario_roles r WHERE activo),'passwords',(SELECT coalesce(jsonb_object_agg(e.email,coalesce(u.email_confirmed_at IS NOT NULL AND length(u.encrypted_password)>0,false)),'{}'::jsonb) FROM (SELECT DISTINCT lower(email) email FROM public.socios WHERE email IS NOT NULL) e LEFT JOIN auth.users u ON lower(u.email)=e.email),'accesos',(SELECT coalesce(jsonb_object_agg(e.email,u.last_sign_in_at IS NOT NULL),'{}'::jsonb) FROM (SELECT DISTINCT lower(email) email FROM public.socios WHERE email IS NOT NULL) e LEFT JOIN auth.users u ON lower(u.email)=e.email)); END $$;